{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipe = pd.read_csv('pipeline_output.csv')

# Let's write our scorer in python and compare column by column.

def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    for item in items:
        v = row[item]
        if pd.isna(v) or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            vals.append(v)

    # self harm flag: q9
    q9 = row['phq9_9']
    if pd.isna(q9) or q9 < 0 or q9 > 3:
        sh_flag = np.nan
    else:
        sh_flag = bool(q9 >= 1)

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan, np.nan, sh_flag
    elif n_missing == 1:
        ans_sum = np.nansum(vals)
        # prorate: sum * 9 / 8, round half up
        from decimal import Decimal, ROUND_HALF_UP
        raw_val = Decimal(ans_sum) * Decimal(9) / Decimal(8)
        total = int(raw_val.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = int(np.nansum(vals))
        prorated = False

    # band
    # 0-4: none-minimal, 5-9: mild, 10-14: moderate, 15-19: moderately severe, 20+: severe
    if total <= 4:
        band = 'none-minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    elif total <= 19:
        band = 'moderately severe'
    else:
        band = 'severe'

    return total, band, prorated, sh_flag

def score_gad7(row):
    items = [f'gad7_{i}' for i in range(1, 8)]
    vals = []
    for item in items:
        v = row[item]
        if pd.isna(v) or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            vals.append(v)

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan, np.nan
    elif n_missing == 1:
        ans_sum = np.nansum(vals)
        from decimal import Decimal, ROUND_HALF_UP
        raw_val = Decimal(ans_sum) * Decimal(7) / Decimal(6)
        total = int(raw_val.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = int(np.nansum(vals))
        prorated = False

    # band: 0-4 minimal, 5-9 mild, 10-14 moderate, 15-21 severe
    if total <= 4:
        band = 'minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    else:
        band = 'severe'

    return total, band, prorated

def score_rses(row):
    items = [f'rses_{i}' for i in range(1, 11)]
    vals = []
    # negative statements: 3, 5, 8, 9, 10
    neg_items = {3, 5, 8, 9, 10}
    for i in range(1, 11):
        item = f'rses_{i}'
        v = row[item]
        if pd.isna(v) or v < 0 or v > 3:
            vals.append(np.nan)
        else:
            if i in neg_items:
                vals.append(3 - v)
            else:
                vals.append(v)

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan
    elif n_missing == 1:
        ans_sum = np.nansum(vals)
        from decimal import Decimal, ROUND_HALF_UP
        raw_val = Decimal(ans_sum) * Decimal(10) / Decimal(9)
        total = int(raw_val.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = int(np.nansum(vals))
        prorated = False

    return total, prorated

my_results = []
for idx, row in raw.iterrows():
    p_tot, p_band, p_pro, p_sh = score_phq9(row)
    g_tot, g_band, g_pro = score_gad7(row)
    r_tot, r_pro = score_rses(row)
    my_results.append({
        'respondent_id': row['respondent_id'],
        'phq9_total': p_tot,
        'phq9_band': p_band,
        'phq9_prorated': p_pro,
        'phq9_self_harm_flag': p_sh,
        'gad7_total': g_tot,
        'gad7_band': g_band,
        'gad7_prorated': g_pro,
        'rses_total': r_tot,
        'rses_prorated': r_pro
    })

my_df = pd.DataFrame(my_results)

# Compare with pipe
for col in pipe.columns:
    if col == 'respondent_id':
        continue
    # compare handling NaNs properly
    mismatches = (my_df[col].values != pipe[col].values) & ~(pd.isna(my_df[col].values) & pd.isna(pipe[col].values))
    n_mismatch = mismatches.sum()
    print(f"Column {col}: {n_mismatch} mismatches")
    if n_mismatch > 0:
        diff_df = pd.DataFrame({
            'id': raw['respondent_id'][mismatches],
            'my': my_df[col][mismatches],
            'pipe': pipe[col][mismatches]
        })
        print(diff_df.head(10))
